package cl.acis.catalogos.model; import jakarta.persistence.*;
@Entity @Table(name="clientes",uniqueConstraints=@UniqueConstraint(name="uk_cliente_rut",columnNames="rut")) public class Cliente { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) String razonSocial; @Column(nullable=false,unique=true) String rut; String contacto,correo,telefono,direccion; Integer slaHoras; @Column(nullable=false) boolean activo=true; public Cliente(){} public Long getId(){return id;} public String getRazonSocial(){return razonSocial;} public void setRazonSocial(String v){razonSocial=v;} public String getRut(){return rut;} public void setRut(String v){rut=v;} public String getContacto(){return contacto;} public void setContacto(String v){contacto=v;} public String getCorreo(){return correo;} public void setCorreo(String v){correo=v;} public String getTelefono(){return telefono;} public void setTelefono(String v){telefono=v;} public String getDireccion(){return direccion;} public void setDireccion(String v){direccion=v;} public Integer getSlaHoras(){return slaHoras;} public void setSlaHoras(Integer v){slaHoras=v;} public boolean isActivo(){return activo;} public void setActivo(boolean v){activo=v;} }
